select * from customer limit 5
-- Q1. What is the total revenue generated by male vs. female customers?
SELECT
    "Gender",
    SUM("Purchase Amount (USD)") AS 
	revenue
FROM customer
GROUP BY "Gender";

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT *
FROM customer
WHERE "Discount Applied" = 'Yes'
AND "Purchase Amount (USD)" > (
    SELECT AVG("Purchase Amount (USD)")
    FROM customer
);
-- Q3. Which are the top 5 products with the highest average review rating?
SELECT
    "Item Purchased",
    AVG("Review Rating") AS average_rating
FROM customer
GROUP BY "Item Purchased"
ORDER BY average_rating DESC
LIMIT 5;
-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT
    "Shipping Type",
    AVG("Purchase Amount (USD)") AS average_purchase
FROM customer
WHERE "Shipping Type" IN ('Standard', 'Express')
GROUP BY "Shipping Type";
-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT
    "Subscription Status",
    AVG("Purchase Amount (USD)") AS average_spend,
    SUM("Purchase Amount (USD)") AS total_revenue
FROM customer
GROUP BY "Subscription Status"
ORDER BY average_spend DESC;
-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT
    "Item Purchased",
    COUNT(*) AS total_purchases,
    SUM(
        CASE
            WHEN "Discount Applied" = 'Yes' THEN 1
            ELSE 0
        END
    ) * 100.0 / COUNT(*) AS discount_percentage
FROM customer
GROUP BY "Item Purchased"
ORDER BY discount_percentage DESC
LIMIT 5;
-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases.
SELECT
    "CustomerID",
    "Previous Purchases",
    CASE
        WHEN "Previous Purchases" <= 1 THEN 'New'
        WHEN "Previous Purchases" BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment
FROM customer
ORDER BY "Previous Purchases" DESC;
--Q8. What are the top 3 most purchased products within each category?
WITH Product_Ranking AS (
    SELECT
        "Category",
        "Item Purchased",
        COUNT(*) AS total_purchases,
        DENSE_RANK() OVER (
            PARTITION BY "Category"
            ORDER BY COUNT(*) DESC
        ) AS product_rank
    FROM customer
    GROUP BY "Category", "Item Purchased"
)
SELECT
    "Category",
    "Item Purchased",
    total_purchases,
    product_rank
FROM Product_Ranking
WHERE product_rank <= 3
ORDER BY "Category", product_rank;
-- Q9. Which age group has the highest average purchase amount?
SELECT
    CASE
        WHEN "Age" BETWEEN 18 AND 25 THEN '18-25'
        WHEN "Age" BETWEEN 26 AND 35 THEN '26-35'
        WHEN "Age" BETWEEN 36 AND 45 THEN '36-45'
        WHEN "Age" BETWEEN 46 AND 55 THEN '46-55'
        ELSE '56+'
    END AS age_group,
    AVG("Purchase Amount (USD)") AS average_purchase
FROM customer
GROUP BY age_group
ORDER BY average_purchase DESC;
-- Q10. Which season generates the highest total purchase revenue?
SELECT
    "Season",
    SUM("Purchase Amount (USD)") AS total_revenue
FROM customer
GROUP BY "Season"
ORDER BY total_revenue DESC;